let campaigns=[],points=[],activeCampaign=null,samplingOrg=null,samplingVersion=0;
const localDate=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
function inRing(lon,lat,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[j],b=ring[i];const cross=(lon-a[0])*(b[1]-a[1])-(lat-a[1])*(b[0]-a[0]);if(Math.abs(cross)<1e-10&&lon>=Math.min(a[0],b[0])&&lon<=Math.max(a[0],b[0])&&lat>=Math.min(a[1],b[1])&&lat<=Math.max(a[1],b[1]))return true;if((a[1]>lat)!==(b[1]>lat)&&lon<(b[0]-a[0])*(lat-a[1])/(b[1]-a[1])+a[0])inside=!inside}return inside}
function inBoundary(lon,lat,g){if(!g)return true;const polygons=g.type==='Polygon'?[g.coordinates]:g.coordinates;return polygons.some(r=>inRing(lon,lat,r[0])&&!r.slice(1).some(h=>inRing(lon,lat,h)))}
async function renderSampling(){const version=++samplingVersion;$('#title').textContent='Amostragem de solo';$('#subtitle').textContent='Planeje campanhas e acompanhe a coleta por ponto.';$('#add').hidden=true;if(!org){$('#content').innerHTML='<div class="panel">Crie ou selecione uma consultoria para iniciar.</div>';return}const orgId=org.id;$('#content').innerHTML='<div class="panel">Carregando campanhas…</div>';try{const rows=await request('/rest/v1/sampling_campaigns?select=*&consultancy_id=eq.'+orgId+'&order=planned_date.desc');if(version!==samplingVersion||page!=='Amostragem'||org?.id!==orgId)return;campaigns=rows;if(samplingOrg!==orgId){activeCampaign=null;samplingOrg=orgId}activeCampaign=campaigns.find(c=>c.id===activeCampaign?.id)||campaigns[0]||null;points=activeCampaign?await request('/rest/v1/sampling_points?select=*&campaign_id=eq.'+activeCampaign.id+'&consultancy_id=eq.'+orgId+'&order=code.asc'):[];if(version!==samplingVersion||page!=='Amostragem'||org?.id!==orgId)return;drawSampling()}catch(e){if(page==='Amostragem')$('#content').innerHTML='<div class="panel error">'+esc(e.message)+'</div>'}}
function drawSampling(){const field=db.fields.find(f=>f.id===activeCampaign?.field_id);$('#content').innerHTML='<div class="toolbar"><select id="campaign-select" aria-label="Campanha"><option value="">Selecione uma campanha</option>'+campaigns.map(c=>'<option value="'+c.id+'" '+(c.id===activeCampaign?.id?'selected':'')+'>'+esc(c.name)+' · '+esc(db.fields.find(f=>f.id===c.field_id)?.name||'Talhão')+'</option>').join('')+'</select><button class="primary" id="new-campaign">+ Nova campanha</button>'+(activeCampaign?'<button id="edit-campaign">Editar campanha</button><button id="delete-campaign">Excluir campanha</button>':'')+'</div>'+(activeCampaign?'<div class="cards"><div class="card"><small>Profundidade</small><strong>'+fmt(activeCampaign.depth_from_cm)+'–'+fmt(activeCampaign.depth_to_cm)+' cm</strong><span>'+esc(field?.name)+'</span></div><div class="card"><small>Data planejada</small><strong>'+esc(activeCampaign.planned_date.split('-').reverse().join('/'))+'</strong></div><div class="card"><small>Coleta</small><strong>'+points.filter(p=>p.status==='collected').length+' / '+points.length+'</strong><span>pontos coletados</span></div></div><div class="panel"><div class="toolbar"><button id="manual-point">+ Ponto por coordenadas</button><label><input type="checkbox" id="map-add"> Adicionar pontos ao clicar no mapa</label><button id="csv-points">Exportar CSV</button></div>'+map(field?[field]:[],{onReady:mountSamplingPoints})+'<p>'+esc(activeCampaign.notes)+'</p><table><thead><tr><th>Código</th><th>Latitude / Longitude</th><th>Estado</th><th>Ações</th></tr></thead><tbody>'+points.map(p=>'<tr><td>'+esc(p.code)+'</td><td>'+p.latitude.toFixed(6)+' / '+p.longitude.toFixed(6)+'</td><td>'+(p.status==='collected'?'Coletado em '+esc(p.collected_on):'Planejado')+'</td><td><button data-point-edit="'+p.id+'">Editar</button><button data-point-delete="'+p.id+'">Excluir</button></td></tr>').join('')+'</tbody></table>'+(!points.length?'<p>Nenhum ponto cadastrado. Ative a opção acima e clique dentro do talhão.</p>':'')+'</div>':'<div class="panel"><h2>Organize sua primeira coleta</h2><p>Cadastre um talhão e crie uma campanha com data e profundidade de amostragem.</p></div>');$('#new-campaign').onclick=()=>campaignForm();$('#campaign-select').onchange=e=>{activeCampaign=campaigns.find(c=>c.id===e.target.value)||null;renderSampling()};if(!activeCampaign)return;$('#edit-campaign').onclick=()=>campaignForm(activeCampaign);$('#delete-campaign').onclick=async()=>{if(points.length){alert('Exclua os pontos antes de excluir a campanha.');return}if(confirm('Excluir esta campanha?'))try{await samplingDelete('sampling_campaigns',activeCampaign.id);activeCampaign=null;await renderSampling()}catch(e){alert(e.message)}};$('#manual-point').onclick=()=>pointForm();$('#csv-points').onclick=exportPoints;document.querySelectorAll('[data-point-edit]').forEach(b=>b.onclick=()=>pointForm(points.find(p=>p.id===b.dataset.pointEdit)));document.querySelectorAll('[data-point-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Excluir este ponto?'))try{await samplingDelete('sampling_points',b.dataset.pointDelete);await renderSampling()}catch(e){alert(e.message)}})}
function mountSamplingPoints(m){for(const p of points)L.circleMarker([p.latitude,p.longitude],{radius:8,color:'#fff',weight:2,fillColor:p.status==='collected'?'#258444':'#d3811f',fillOpacity:1}).addTo(m).bindTooltip(esc(p.code),{permanent:true,direction:'top'}).bindPopup(esc(p.code)+' · '+(p.status==='collected'?'Coletado':'Planejado'));m.on('click',e=>{if(!$('#map-add')?.checked)return;const field=db.fields.find(f=>f.id===activeCampaign.field_id);if(!inBoundary(e.latlng.lng,e.latlng.lat,geometryOf(field||{}))){alert('Selecione um ponto dentro dos limites do talhão.');return}pointForm(null,e.latlng)})}
function sampleDialog(title,html,submit){let d=document.getElementById('sample-dialog');if(!d){d=document.createElement('dialog');d.id='sample-dialog';document.body.append(d)}d.innerHTML='<form id="sample-form"><div class="dialoghead"><h2>'+title+'</h2><button type="button" id="sample-close" aria-label="Fechar">×</button></div>'+html+'<p class="error" id="sample-error" role="alert"></p><button class="primary" id="sample-save">Salvar</button></form>';$('#sample-close').onclick=()=>d.close();$('#sample-form').onsubmit=async e=>{e.preventDefault();$('#sample-save').disabled=true;try{await submit(Object.fromEntries(new FormData(e.target)));d.close();await renderSampling()}catch(err){$('#sample-error').textContent=err.message}finally{$('#sample-save').disabled=false}};d.showModal()}
function campaignForm(c){if(!db.fields.length){alert('Cadastre um talhão antes de criar a campanha.');return}sampleDialog(c?'Editar campanha':'Nova campanha',field('Nome','name',c?.name||'')+select('Talhão','field_id','fields',c?.field_id)+field('Data planejada','planned_date',c?.planned_date||localDate(),'date')+field('Profundidade inicial (cm)','depth_from_cm',c?.depth_from_cm??0,'number')+field('Profundidade final (cm)','depth_to_cm',c?.depth_to_cm??20,'number')+'<label>Observações<textarea name="notes" maxlength="4000">'+esc(c?.notes||'')+'</textarea></label>',async data=>{data.name=data.name.trim();data.depth_from_cm=Number(data.depth_from_cm);data.depth_to_cm=Number(data.depth_to_cm);if(!data.name||data.depth_from_cm<0||data.depth_to_cm<=data.depth_from_cm||data.depth_to_cm>300)throw Error('Confira o nome e o intervalo de profundidade.');if(c&&points.length&&data.field_id!==c.field_id)throw Error('Uma campanha com pontos deve permanecer no mesmo talhão.');const result=await samplingWrite('sampling_campaigns',data,c?.id);activeCampaign=result[0]})}
function pointForm(p,latlng){const campaignId=activeCampaign.id;let number=points.length+1;while(points.some(p=>p.code==='P'+String(number).padStart(3,'0')))number++;sampleDialog(p?'Editar ponto':'Novo ponto',field('Código da amostra','code',p?.code||'P'+String(number).padStart(3,'0'))+field('Latitude (graus decimais)','latitude',p?.latitude??latlng?.lat??'','number')+field('Longitude (graus decimais)','longitude',p?.longitude??latlng?.lng??'','number')+'<label>Estado<select name="status"><option value="planned">Planejado</option><option value="collected" '+(p?.status==='collected'?'selected':'')+'>Coletado</option></select></label><label>Data da coleta<input name="collected_on" type="date" value="'+esc(p?.collected_on||'')+'"></label><label>Observações<textarea name="notes" maxlength="4000">'+esc(p?.notes||'')+'</textarea></label>',async data=>{data.code=data.code.trim();data.latitude=Number(data.latitude);data.longitude=Number(data.longitude);data.campaign_id=campaignId;data.collected_on=data.status==='collected'?data.collected_on:null;if(!data.code||!Number.isFinite(data.latitude)||!Number.isFinite(data.longitude)||Math.abs(data.latitude)>90||Math.abs(data.longitude)>180)throw Error('Confira o código e as coordenadas.');if(data.status==='collected'&&!data.collected_on)throw Error('Informe a data da coleta.');const field=db.fields.find(f=>f.id===activeCampaign.field_id);if(!inBoundary(data.longitude,data.latitude,geometryOf(field||{})))throw Error('O ponto está fora dos limites do talhão.');await samplingWrite('sampling_points',data,p?.id)});document.querySelectorAll('#sample-form input[type=number]').forEach(i=>i.step='any')}
async function samplingWrite(table,data,id){const result=await request('/rest/v1/'+table+(id?'?id=eq.'+id+'&consultancy_id=eq.'+org.id:''),id?'PATCH':'POST',{...data,consultancy_id:org.id,...(!id?{id:crypto.randomUUID()}:{})});if(!result?.length)throw Error('Registro não salvo. Confira suas permissões.');return result}
async function samplingDelete(table,id){const result=await request('/rest/v1/'+table+'?id=eq.'+id+'&consultancy_id=eq.'+org.id,'DELETE');if(!result?.length)throw Error('Exclusão não permitida.')}
function exportPoints(){const cell=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@]/,"'$&")+'"';const rows=[['campanha','talhao','codigo','latitude','longitude','profundidade_inicial_cm','profundidade_final_cm','estado','data_coleta','observacoes'],...points.map(p=>[activeCampaign.name,db.fields.find(f=>f.id===activeCampaign.field_id)?.name,p.code,p.latitude,p.longitude,activeCampaign.depth_from_cm,activeCampaign.depth_to_cm,p.status,p.collected_on,p.notes])];const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='amostragem-'+activeCampaign.id+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
